   *
   * @param {CssPseudo} cssPseudo CSS Pseudo class
   * @returns {string} Pseudo selector parsed as UiSelector
   */
  parsePseudo (cssPseudo) {
    if (cssPseudo.valueType && cssPseudo.valueType !== 'string') {
